class Problem {
    // Find the shortest palindrome that begins with a supplied string.
    // Algorithm idea is simple:
    // - Find the longest postfix of supplied string that is a palindrome.
    // - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    // >>> makePalindrome((""))
    // ("")
    // >>> makePalindrome(("cat"))
    // ("catac")
    // >>> makePalindrome(("cata"))
    // ("catac")
    public static String makePalindrome(String string) {
if (string.isEmpty()) return "";
        for (int i = 0; i < string.length(); i++) {
            String suffix = string.substring(i);
            String reversed = new StringBuilder(suffix).reverse().toString();
            if (suffix.equals(reversed)) {
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }
        return string + new StringBuilder(string).reverse().toString();
    }
    public static void main(String[] args) {
    assert(makePalindrome(("")).equals(("")));
    assert(makePalindrome(("x")).equals(("x")));
    assert(makePalindrome(("xyz")).equals(("xyzyx")));
    assert(makePalindrome(("xyx")).equals(("xyx")));
    assert(makePalindrome(("jerry")).equals(("jerryrrej")));
    }

}

