        boolean hasOdd = false;
        String s = Long.toString(n);
        for (char c : s.toCharArray()) {
            int digit = c - '0';
            if (digit % 2 != 0) {
                product *= digit;
                hasOdd = true;
            }
        }
        return hasOdd ? product : 0;
    }
