class Problem {
    // Write a function to find the index of the first occurrence of a given number in a sorted array array list.
    public static long findFirstOccurrence(ArrayList<Long> A, long x) {
int low = 0, high = A.size() - 1;
        long result = -1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (A.get(mid) == x) {
                result = mid;
                high = mid - 1;
            } else if (A.get(mid) < x) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
