import java.util.*;
import java.lang.reflect.*;
import org.javatuples.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;
class Problem {
    // Write a javathon function to find the first odd number in a given array list of numbers.
    public static long firstOdd(ArrayList<Long> nums) {
for (Long num : nums) {
            if (num % 2 != 0) {
                return num;
            }
        }
        return -1;
    }
    public static void main(String[] args) {
    assert(firstOdd((new ArrayList<Long>(Arrays.asList((long)1l, (long)3l, (long)5l)))) == (1l));
    assert(firstOdd((new ArrayList<Long>(Arrays.asList((long)2l, (long)4l, (long)1l, (long)3l)))) == (1l));
    assert(firstOdd((new ArrayList<Long>(Arrays.asList((long)8l, (long)9l, (long)1l)))) == (9l));
    }

}

